import heapq


class SearchQueue:

    def __init__(self):
        self._heap = []
        self._counter = 0

    def push(self, priority, item):
        heapq.heappush(self._heap, (priority, self._counter, item))
        self._counter += 1

    def pop(self):
        if not self._heap:
            raise IndexError("pop from an empty SearchQueue")
        return heapq.heappop(self._heap)[2]

    def __len__(self):
        return len(self._heap)

