class TilePuzzle(object):

    def __init__(self, board):
        self.board = board

    def get_board(self):
        return self.board

    def perform_move(self, direction):
        offsets = {"up": (-1, 0), "down": (1, 0),
                   "left": (0, -1), "right": (0, 1)}
        if direction not in offsets:
            return False
        rows, cols = len(self.board), len(self.board[0])
        dr, dc = offsets[direction]
